package store.cadera.cdrjobs.api.event;
import org.bukkit.entity.Player;import org.bukkit.event.Event;import org.bukkit.event.HandlerList;import org.jetbrains.annotations.NotNull;import store.cadera.cdrjobs.model.JobType;
public final class ProfessionLevelUpEvent extends Event {private static final HandlerList HANDLERS=new HandlerList();private final Player player;private final JobType profession;private final int oldLevel,newLevel;public ProfessionLevelUpEvent(Player p,JobType j,int o,int n){player=p;profession=j;oldLevel=o;newLevel=n;}public Player getPlayer(){return player;}public JobType getProfession(){return profession;}public int getOldLevel(){return oldLevel;}public int getNewLevel(){return newLevel;}@Override public @NotNull HandlerList getHandlers(){return HANDLERS;}public static HandlerList getHandlerList(){return HANDLERS;}}
